INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65396813', 65396813, 'analyze_legacy', 'Kab. Banyuwangi', 'kabkota', 'Dinas Pertanian dan Pangan', 'Pembangunan Jaringan Irigasi Tersier di Desa Sragi Kecamatan Songgon', 'Pekerjaan Konstruksi', 'E-Purchasing', 'Jawa Timur, Banyuwangi (Kab.)', 92620000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'Pekerjaan Pembangunan Jaringan Irigasi Tersier di Desa Sragi Kecamatan Songgon ini dimulai dengan tahap persiapan yang mencakup survei pengukuran lapangan, dilanjutkan dengan pekerjaan tanah berupa penggalian serta pemadatan untuk membentuk profil saluran yang sesuai desain. Konstruksi fisik kemudian dilakukan dengan membangun saluran pembawa menggunakan pasangan batu, serta pemasangan boks tersier dan kuarter (apabila diperlukan) untuk mendistribusikan air secara merata ke petak sawah petani. Seluruh proses ini diakhiri dengan tahap Pembersihan Lokasi.', 'Pekerjaan ini mencakup : persiapan, galian saluran, timbunan tanah, pasangan batu (Batu Belah Mortar Tipe N), siaran (Dengan Mortar Jenis Pc-Pp Tipe M (17,2 Mpa)), dan plesteran (Tebal 1,5 Cm, Dengan Mortar Tipe N (5,2 Mpa)). Dimensi saluran, lebar, tinggi, dan kemiringan (slope) disesuaikan dengan debit air dan kondisi lapangan untuk meningkatkan atau mempertahankan intensitas tanam (IP).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2120359);
