INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65438252', 65438252, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Penambah Daya Tahan Tubuh Untuk Pemenuhan Kegiatan Kesehatan Pegawai Pada Inspektorat jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 275310000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '14490.0 OH', 'Pengadaan Penambah Daya Tahan Tubuh dalam bentuk sirup untuk pemenuhan kegiatan kesehatan pegawai pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 bertujuan untuk mendukung pemeliharaan kesehatan serta meningkatkan daya tahan tubuh pegawai guna menunjang produktivitas kerja. Pelaksanaan pekerjaan meliputi penyediaan penambah daya tahan tubuh yang memenuhi standar mutu, keamanan, dan legalitas sesuai dengan ketentuan peraturan perundang-undangan yang berlaku, memiliki izin edar resmi dari BPOM, serta dalam kondisi baru dan tersegel pabrik. Kebutuhan pengadaan diperuntukkan bagi 161 orang pegawai, diberikan selama 15 hari dalam setiap bulan dan dilaksanakan selama 6 bulan.', 'Spesifikasi teknis pengadaan Penambah Daya Tahan Tubuh untuk pemenuhan kegiatan kesehatan pegawai pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 dengan volume sebesar 14.490,0 OH berupa suplemen kesehatan dalam bentuk sediaan padat, yaitu tablet atau kapsul, yang diproduksi secara massal dan beredar resmi di pasaran Indonesia. Produk dikemas dalam kemasan standar pabrikan seperti strip, blister, atau botol, dalam kondisi baru dan tersegel dengan baik, serta siap konsumsi sesuai aturan pakai. Setiap kemasan wajib mencantumkan informasi produk, komposisi umum, aturan penggunaan, nomor izin edar yang masih berlaku, nomor batch, serta tanggal kedaluwarsa dengan sisa masa simpan yang memadai pada saat serah terima. Barang yang disediakan harus sesuai dengan jumlah kebutuhan dan dalam kondisi baik pada saat pemeriksaan dan penyerahan.', 137655000, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2124675);
