INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65439606', 65439606, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'DINAS PEKERJAAN UMUM DAN PENATAAN RUANG', 'Penyusunan Data dan lnventarisasi Aset lntrastruktur Jalan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 97001000, 'February 2026', 'APBD', 1, 1, '1', 'Ruang lingkup pekerjaan meliputi: a. Penyusunan rencana kerja, metodologi survei, format formulir inventarisasi, serta sistem klasifikasi dan pengkodean aset. b. Koordinasi dengan perangkat daerah dan pihak terkait dalam rangka pelaksanaan kegiatan inventarisasi aset. c. Pelaksanaan survei lapangan untuk pendataan seluruh aset infrastruktur jalan beserta bangunan pelengkap dan perlengkapannya yang berada di sepanjang koridor jalan kewenangan Kota Tangerang. d. Pengumpulan dan penelaahan data sekunder terkait ruas jalan berstatus kewenangan Kota Tangerang, peta dasar, data jaringan jalan, serta data pendukung lainnya. e. Pengumpulan dan verifikasi dokumen penyerahan atau pembebasan aset infrastruktur jalan dari pengembang dan/atau pihak swasta kepada Pemerintah Kota Tangerang. f. Pendataan dan identifikasi aset infrastruktur jalan hasil penyerahan atau pembebasan dari pengembang dan/atau pihak swasta. g. Pengambilan data koordinat lokasi aset, dokumentasi foto kondisi eksisting, serta pencatatan data teknis aset meliputi jenis, dimensi, fungsi, dan kondisi fisik. h. Pengolahan, penginputan, dan validasi data hasil survei lapangan ke dalam basis data terstruktur. i. Penyusunan peta inventarisasi aset infrastruktur jalan berbasis sistem informasi geografis (SIG). j. Penyusunan basis data aset infrastruktur jalan yang terintegrasi dan mudah diperbarui. k. Penyusunan laporan pendahuluan, laporan antara, dan laporan akhir pekerjaan. l. Penyerahan hasil pekerjaan berupa laporan, peta, dan basis data digital sesuai ketentuan Kerangka Acuan Kerja.', '1 Orang Team Leader Teknik Ahli Teknik Jalan/Geodesi/Geoteknik Ahli Muda S1 Pengalaman 3 Tahun; 5 Orang Tenaga Pendukung Surveyor; 1 Orang Tenaga Pendukung Operator SIG.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2127374);
